kw_goto_ifzero_n:
			pop hl
			ld a, (hl)
			inc hl
			or (hl)
			pop hl
			jp nz, ntc_xn
			ld sp, hl
			jp ntc_xn

ntc_rg107_e:
			IF ($ < 37888) && (ntc_rg108_e - ntc_rg108 + $ > 16384)	; fwdref-ok
