ntc_rg114:
;## kw_addl
;kw_addl, <var>, <literal>, <destvar>
kw_addl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			add hl, de
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

ntc_rg114_e:
			IF ($ < 37888) && (ntc_rg115_e - ntc_rg115 + $ > 16384)	; fwdref-ok
