			ld (ntc_mode), a
			jp ntc_divvl

ntc_rg119_e:
			IF ($ < 37888) && (ntc_rg120_e - ntc_rg120 + $ > 16384)	; fwdref-ok
			ds 37888 - $		; Option Reserve #4000-#93FF: round it
			ENDIF
ntc_rg120:
;## kw_andvv
;kw_andvv, <var1>, <var2>, <destvar>
kw_andvv:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			and e
			ld e, a
			inc hl
			ld a, (hl)
			and d
			ld d, a
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

ntc_rg120_e:
			IF ($ < 37888) && (ntc_rg121_e - ntc_rg121 + $ > 16384)	; fwdref-ok
			ds 37888 - $		; Option Reserve #4000-#93FF: round it
			ENDIF
ntc_rg121:
;## kw_orvv
;kw_orvv, <var1>, <var2>, <destvar>
kw_orvv:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			or e
			ld e, a
			inc hl
			ld a, (hl)
			or d
			ld d, a
			pop hl
			ld (hl), e
			inc hl
