			ENDIF
ntc_rg131:
;## ntc_itoa ntc_data
; HL = signed value, DE = buffer: writes the digits and a 0 (DE ends on
; the 0). jp (ix) back. Uses A, BC, IY.
ntc_itoa:
			bit 7, h
			jr z, ntc_ia_pos
			ld a, '-'
			ld (de), a
			inc de
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_ia_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_pow10
ntc_ia_pow:
			ld c, (iy+0)
			ld b, (iy+1)
			ld a, b
			or c
			jr z, ntc_ia_last
			ld a, '0' - 1
ntc_ia_sub:
			inc a
			and a
			sbc hl, bc
			jr nc, ntc_ia_sub
			add hl, bc
			cp '0'
			jr nz, ntc_ia_out
			ld b, a
			ld a, (ntc_lead)
			or a
			ld a, b
			jr z, ntc_ia_skip
ntc_ia_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_ia_skip:
			inc iy
			inc iy
			jr ntc_ia_pow
ntc_ia_last:
			ld a, l
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_pow10:		dw 10000, 1000, 100, 10, 0

ntc_rg131_e:
			IF ($ < 37888) && (ntc_rg132_e - ntc_rg132 + $ > 16384)	; fwdref-ok
			ds 37888 - $		; Option Reserve #4000-#93FF: round it
			ENDIF
ntc_rg132:
;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld de, ntc_numbuf
			ld ix, ntc_pi_done
			jp ntc_itoa
ntc_pi_done:
			ld hl, ntc_numbuf
			ld (ntc_sptr), hl
			jp ntc_printbuf

ntc_rg132_e:
			IF ($ < 37888) && (ntc_rg133_e - ntc_rg133 + $ > 16384)	; fwdref-ok
			ds 37888 - $		; Option Reserve #4000-#93FF: round it
			ENDIF
ntc_rg133:
;## kw_printnl0 ntc_data ntc_plat_screen
;kw_printnl0  - new line unless the cursor is at the start of a line
kw_printnl0:
			ld a, (ntc_curx)
			or a
			ret z
			ld ix, ntc_next
			jp ntc_plat_newline

ntc_rg133_e:
			IF ($ < 37888) && (ntc_rg134_e - ntc_rg134 + $ > 16384)	; fwdref-ok
			ds 37888 - $		; Option Reserve #4000-#93FF: round it
			ENDIF
ntc_rg134:
;## kw_printnl ntc_data ntc_plat_screen
;kw_printnl
kw_printnl:
			ld ix, ntc_next
			jp ntc_plat_newline

ntc_rg134_e:
			IF ($ < 37888) && (ntc_rg135_e - ntc_rg135 + $ > 16384)	; fwdref-ok
			ds 37888 - $		; Option Reserve #4000-#93FF: round it
			ENDIF
ntc_rg135:
;## kw_inkey ntc_data ntc_plat_key
;kw_inkey, <destvar>  - new key press or 0, no wait
kw_inkey:
			pop hl
			ld (ntc_ivar), hl
			ld ix, ntc_inkey_got
			jp ntc_plat_scankey
ntc_inkey_got:
			ld hl, (ntc_ivar)
			ld (hl), a
			inc hl
			ld (hl), 0
			ret

ntc_rg135_e:
			IF ($ < 37888) && (ntc_rg136_e - ntc_rg136 + $ > 16384)	; fwdref-ok
			ds 37888 - $		; Option Reserve #4000-#93FF: round it
			ENDIF
ntc_rg136:
;## kw_cls ntc_data ntc_plat_screen
;kw_cls
kw_cls:
			ld ix, ntc_next
			jp ntc_plat_cls

ntc_rg136_e:
			IF ($ < 37888) && (ntc_rg137_e - ntc_rg137 + $ > 16384)	; fwdref-ok
			ds 37888 - $		; Option Reserve #4000-#93FF: round it
			ENDIF
ntc_rg137:
;## kw_locatell ntc_data ntc_plat_screen
;kw_locatell, <x>, <y>  - 1 based
kw_locatell:
			pop bc
			pop de
			ld h, c
			ld l, e
			ld ix, ntc_next
			jp ntc_plat_locate

ntc_rg137_e:
			IF ($ < 37888) && (ntc_rg138_e - ntc_rg138 + $ > 16384)	; fwdref-ok
			ds 37888 - $		; Option Reserve #4000-#93FF: round it
			ENDIF
ntc_rg138:
;## kw_model ntc_data ntc_plat_screen
;kw_model, <literal>  - 0, 1 or 2, clears the screen
kw_model:
			pop hl
			ld a, l
			ld ix, ntc_next
			jp ntc_plat_mode

ntc_rg138_e:
			IF ($ < 37888) && (ntc_rg139_e - ntc_rg139 + $ > 16384)	; fwdref-ok
			ds 37888 - $		; Option Reserve #4000-#93FF: round it
			ENDIF
ntc_rg139:
;## kw_ticks ntc_data ntc_plat_ticks
;kw_ticks, <destvar>  - tick count from the platform (CPC: interrupts, 300 a second,
;  only moving in normal mode)
kw_ticks:
			pop hl
			ld (ntc_ivar), hl
			ld ix, ntc_tk_got
			jp ntc_plat_ticks
ntc_tk_got:
			ex de, hl
			ld hl, (ntc_ivar)
			ld (hl), e
			inc hl
			ld (hl), d
			ret

; ============================================================
; String functions. Numbers are passed as the address of a word
; (a literal goes in as lit_n, a dw in the data). Results go to a
; string buffer (41 bytes). Dest may be the same as the source.
; ============================================================

ntc_rg139_e:
			IF ($ < 37888) && (ntc_rg140_e - ntc_rg140 + $ > 16384)	; fwdref-ok
			ds 37888 - $		; Option Reserve #4000-#93FF: round it
			ENDIF
ntc_rg140:
;## kw_strhex
;kw_strhex, <dest>, <nvar>  - Hex$(n), no leading zeros
kw_strhex:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld b, 4
			ld c, 0
ntc_hx_loop:
			xor a
			add hl, hl
			rla
			add hl, hl
			rla
			add hl, hl
			rla
			add hl, hl
			rla
			bit 0, c
			jr nz, ntc_hx_out
			or a
			jr nz, ntc_hx_first
			ld a, b
			dec a
			jr nz, ntc_hx_next
			xor a
ntc_hx_first:
			set 0, c
ntc_hx_out:
			add a, '0'
			cp '9' + 1
			jr c, ntc_hx_put
			add a, 7
ntc_hx_put:
			ld (de), a
			inc de
ntc_hx_next:
			djnz ntc_hx_loop
			xor a
			ld (de), a
			ret

ntc_rg140_e:
			IF ($ < 37888) && (ntc_rg141_e - ntc_rg141 + $ > 16384)	; fwdref-ok
			ds 37888 - $		; Option Reserve #4000-#93FF: round it
			ENDIF
ntc_rg141:
;## kw_l_mov
;kw_l_mov, <src>, <dest>  - dest = src (4 bytes)
kw_l_mov:
			pop hl
			pop de
			ldi
			ldi
			ldi
			ldi
			ret

ntc_rg141_e:
			IF ($ < 37888) && (ntc_rg142_e - ntc_rg142 + $ > 16384)	; fwdref-ok
			ds 37888 - $		; Option Reserve #4000-#93FF: round it
			ENDIF
ntc_rg142:
;## ntc_keys ntc_data @shared
; ------------------------------------------------------------
; ntc_keys - the Keys class (CPC): the keyboard matrix read straight from the
; hardware (PSG register 14 through the PPI), all 10 lines each time, so it
; works with or without the firmware, in turbo and normal mode. Entered
; with jp from a method, with the method's result pointer still on the
; thread: the result goes there and ret carries on. No stack used.
;   ntc_kdown - HL = a key number 0-79 (the CPC's, as INKEY(n)): -1 held, 0 not
;   ntc_kjoy  - HL = joystick 0 / 1: bits up 1, down 2, left 4, right 8,
;               fire 2 16, fire 1 32 (as JOY(n))
; ------------------------------------------------------------
ntc_kmat:		ds 10			; the matrix (0 = pressed)
ntc_karg:		db 0
ntc_kwhat:		db 0

ntc_kdown:
			ld a, h
			or a
			jr nz, ntc_kd_no
			ld a, l
			cp 80
			jr nc, ntc_kd_no
			ld (ntc_karg), a
			xor a
			jr ntc_kscan
ntc_kjoy:
			ld a, l
			and 1
			ld (ntc_karg), a
			ld a, 1
ntc_kscan:
			ld (ntc_kwhat), a
			ld bc, #F40E		; PSG register 14
			out (c), c
			ld bc, #F6C0		; PSG: select register
			out (c), c
			ld bc, #F600		; PSG: inactive
			out (c), c
			ld bc, #F792		; PPI port A input
			out (c), c
			ld hl, ntc_kmat
			ld a, #40			; PSG read + line 0
ntc_ksc_line:
			ld b, #F6
			out (c), a
			ld b, #F4
			in d, (c)
			ld (hl), d
			inc hl
			inc a
			cp #4A
			jr nz, ntc_ksc_line
			ld bc, #F782		; PPI port A output
			out (c), c
			ld bc, #F600
			out (c), c
			ld a, (ntc_kwhat)
			or a
			jr nz, ntc_kj_got
			ld a, (ntc_karg)	; line = n / 8, bit = n and 7
			ld c, a
			rrca
			rrca
			rrca
			and 31
			ld e, a
			ld d, 0
			ld hl, ntc_kmat
			add hl, de
			ld a, c
			and 7
			ld b, a
			inc b
			ld a, (hl)
ntc_kd_rot:
			rrca
			djnz ntc_kd_rot
			ld de, 0
			jr c, ntc_k_set		; 1 = not pressed
			dec de
			jr ntc_k_set
ntc_kd_no:
			ld de, 0
			jr ntc_k_set
ntc_kj_got:
			ld a, (ntc_karg)	; joystick 0 = line 9, 1 = line 6
			ld hl, ntc_kmat + 9
			or a
			jr z, ntc_kj_line
			ld hl, ntc_kmat + 6
ntc_kj_line:
			ld a, (hl)
			cpl
			and #3F
			ld e, a
			ld d, 0
ntc_k_set:
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

ntc_rg142_e:
			IF ($ < 37888) && (ntc_rg143_e - ntc_rg143 + $ > 16384)	; fwdref-ok
			ds 37888 - $		; Option Reserve #4000-#93FF: round it
			ENDIF
ntc_rg143:
;## ntc_gfx ntc_data ntc_plat_data @shared @ramonly
; ------------------------------------------------------------
; ntc_gfx - drawing on the CPC screen (Graphics class, Vector3D): lines in
; mode 0, 1 or 2 (ntc_smode), in a pen, XOR (drawing a line again takes it
; off). Two screens for double buffering: #C000 and main RAM's own
; #4000-#7FFF (page 1 - the CRTC always shows main RAM, whatever RAM page the
; Z80 has in the window). Called on the real stack (call / ret); uses IX, IY.
; One loop for every mode: C is a marker of the pixel's bits (mode 0 #AA /
; #55, mode 1 #88 >> n, mode 2 #80 >> n); RRC C moves it one pixel right and
; its carry says "next byte"; the pixel is C and the pen's pattern (IYL).
; ------------------------------------------------------------
gfx_x0:			dw 0
gfx_y0:			dw 0
gfx_x1:			dw 0
gfx_y1:			dw 0
gfx_pen:		db 1
gfx_clip:		db 1			; 1: a line with an end off the screen isn't drawn; 0: no checks
gfx_base:		db #C0			; the screen drawn on (high byte)
gfx_dbl:		db 0			; 1 = double buffering
gfx_shown:		db #30			; CRTC R12 of the screen shown
gfx_sp:			dw 0			; the thread position while a Graphics method works

; gfx_begin / gfx_end - around drawing: main RAM in the window when the
; screen drawn on is #4000, the RAM setting put back after
gfx_begin:
	IF NTC_CPMGFX
			ret						; CP/M: each line does its own (gfx_cpmdraw)
	ENDIF
			ld a, (gfx_base)
			cp #40
			ret nz
			push bc
			ld bc, #7FC0
			out (c), c
			pop bc
			ret
gfx_end:
	IF NTC_CPMGFX
			ret
	ENDIF
			ld a, (gfx_base)
			cp #40
			ret nz
			ld bc, (ntc_rampt)
			out (c), c
			ret

; gfx_width - HL = the screen's width in pixels in this mode
gfx_width:
			ld a, (ntc_smode)
			ld hl, 160
			or a
			ret z
			add hl, hl
			dec a
			ret z
			add hl, hl
			ret

; gfx_line - (gfx_x0, gfx_y0) to (gfx_x1, gfx_y1), pixels of this mode
gfx_line:
			ld a, (gfx_clip)
			or a
			jr z, gfx_l_go
			call gfx_width
			ex de, hl
			ld hl, (gfx_x0)
			call gfx_chk
			ret c
			ld hl, (gfx_x1)
			call gfx_chk
			ret c
			ld de, 200
			ld hl, (gfx_y0)
			call gfx_chk
			ret c
			ld hl, (gfx_y1)
			call gfx_chk
			ret c
gfx_l_go:
			ld hl, (gfx_x1)			; left to right
			ld de, (gfx_x0)
			or a
			sbc hl, de
			jr nc, gfx_l_lr
			ld hl, (gfx_x0)
			ld de, (gfx_x1)
			ld (gfx_x0), de
			ld (gfx_x1), hl
			ld hl, (gfx_y0)
			ld de, (gfx_y1)
			ld (gfx_y0), de
			ld (gfx_y1), hl
			ld hl, (gfx_x1)
			ld de, (gfx_x0)
			or a
			sbc hl, de
gfx_l_lr:
			ld (gfx_dx), hl
			ld hl, (gfx_y1)
			ld de, (gfx_y0)
			or a
			sbc hl, de
			ld a, 0
			jr nc, gfx_l_dy
			call gfx_neg
			ld a, 1
gfx_l_dy:
			ld (gfx_sy), a
			ld (gfx_dy), hl
			call gfx_pat			; IYL = the pen's pattern in this mode
			ld a, (gfx_y0)			; HL = the address of (x0, y0)
			ld c, a
			and #F8
			ld l, a
			ld h, 0
			add hl, hl
			ld d, h
			ld e, l
			add hl, hl
			add hl, hl
			add hl, de				; (y / 8) * 80
			ld a, c
			and 7
			add a, a
			add a, a
			add a, a
			ld c, a
			ld a, (gfx_base)
			add a, c
			add a, h
			ld h, a
			ld de, (gfx_x0)			; + x / pixels a byte, C = the marker
			ld a, (ntc_smode)
			or a
			jr nz, gfx_l_m12
			ld c, #AA
			srl d
			rr e
			jr nc, gfx_l_adr
			ld c, #55
			jr gfx_l_adr
gfx_l_m12:
			dec a
			ld a, e
			jr nz, gfx_l_m2
			and 3
			ld b, a
			ld c, #88
			srl d
			rr e
			srl d
			rr e
			jr gfx_l_sh
gfx_l_m2:
			and 7
			ld b, a
			ld c, #80
			srl d
			rr e
			srl d
			rr e
			srl d
			rr e
gfx_l_sh:
			ld a, b
			or a
			jr z, gfx_l_adr
gfx_l_shl:
			rrc c
			djnz gfx_l_shl
gfx_l_adr:
			add hl, de
	IF NTC_CPMGFX
			jp gfx_cpmdraw
	ELSE
			call gfx_begin
			call gfx_l_draw
			jp gfx_end
	ENDIF
; >gfxhi - CP/M: the compiler copies from here to <gfxhi into common memory
; (GFH_AT, #C000), labels gfx_ renamed gfh_: the copy CP/M Plus draws with
gfx_dx:			dw 0
gfx_dy:			dw 0
gfx_out:		db 0
gfx_sy:			db 0			; 0 down, 1 up
	IF NTC_CPMGFX
; gfx_go (run as gfh_go, in common memory) - CP/M Plus: draw the line with
; RAM configuration C1 (the screen, block 1, at #4000), on a stack in common
; memory (C1 takes away the program's own #0000-#BFFF), then C2 back
gfx_go:
			ld (gfx_hsp), sp
			ld sp, gfx_hstk
			ld a, i					; P/V = interrupts on: off while C1 is in
			di
			push af
			ld a, c
			ld bc, #7FC1
			out (c), c
			ld c, a
			call gfx_l_draw
			ld bc, #7FC2
			out (c), c
			pop af
			ld sp, (gfx_hsp)
			ret po
			ei
			ret
gfx_hsp:		dw 0
				ds 24
gfx_hstk:
	ENDIF
gfx_l_draw:
			ld a, c					; the first pixel
			and iyl
			xor (hl)
			ld (hl), a
			push hl
			ld hl, (gfx_dx)
			ld de, (gfx_dy)
			or a
			sbc hl, de
			pop hl
			jp c, gfx_ymaj
			ld de, (gfx_dy)			; x major: count dx, error dx / 2, IX = dy
			push de
			pop ix
			ld de, (gfx_dx)
			call gfx_cnt
			ret z
			ld de, (gfx_dx)
			srl d
			rr e
			ld a, (gfx_sy)
			or a
			jp nz, gfx_xu
gfx_xd:
			rrc c					; x + 1
			jr nc, gfx_xd1
			inc hl
gfx_xd1:
			ld a, e					; error - dy
			sub ixl
			ld e, a
			ld a, d
			sbc a, ixh
			ld d, a
			jp p, gfx_xd2
			push hl					; error + dx, y + 1
			ld hl, (gfx_dx)
			add hl, de
			ex de, hl
			pop hl
			ld a, h
			add a, 8
			ld h, a
			and #38
			jr nz, gfx_xd2
			push de
			ld de, #C050
			add hl, de
			pop de
gfx_xd2:
			ld a, c
			and iyl
			xor (hl)
			ld (hl), a
			djnz gfx_xd
			ld a, (gfx_out)
			dec a
			ld (gfx_out), a
			jr nz, gfx_xd
			ret
gfx_xu:
			rrc c
			jr nc, gfx_xu1
			inc hl
gfx_xu1:
			ld a, e
			sub ixl
			ld e, a
			ld a, d
			sbc a, ixh
			ld d, a
			jp p, gfx_xu2
			push hl					; error + dx, y - 1
			ld hl, (gfx_dx)
			add hl, de
			ex de, hl
			pop hl
			ld a, h
			sub 8
			ld h, a
			and #38
			cp #38
			jr nz, gfx_xu2
			push de
			ld de, #3FB0
			add hl, de
			pop de
gfx_xu2:
			ld a, c
			and iyl
			xor (hl)
			ld (hl), a
			djnz gfx_xu
			ld a, (gfx_out)
			dec a
			ld (gfx_out), a
			jr nz, gfx_xu
			ret
gfx_ymaj:
			ld de, (gfx_dx)			; y major: count dy, error dy / 2, IX = dx
			push de
			pop ix
			ld de, (gfx_dy)
			call gfx_cnt
			ret z
			ld de, (gfx_dy)
			srl d
			rr e
			ld a, (gfx_sy)
			or a
			jp nz, gfx_yu
gfx_yd:
			ld a, h					; y + 1
			add a, 8
			ld h, a
			and #38
			jr nz, gfx_yd1
			push de
			ld de, #C050
			add hl, de
			pop de
gfx_yd1:
			ld a, e					; error - dx
			sub ixl
			ld e, a
			ld a, d
			sbc a, ixh
			ld d, a
			jp p, gfx_yd2
			push hl					; error + dy, x + 1
			ld hl, (gfx_dy)
			add hl, de
			ex de, hl
			pop hl
			rrc c
			jr nc, gfx_yd2
			inc hl
gfx_yd2:
			ld a, c
			and iyl
			xor (hl)
			ld (hl), a
			djnz gfx_yd
			ld a, (gfx_out)
			dec a
			ld (gfx_out), a
			jr nz, gfx_yd
			ret
gfx_yu:
			ld a, h					; y - 1
			sub 8
			ld h, a
			and #38
			cp #38
			jr nz, gfx_yu1
			push de
			ld de, #3FB0
			add hl, de
			pop de
gfx_yu1:
			ld a, e
			sub ixl
			ld e, a
			ld a, d
			sbc a, ixh
			ld d, a
			jp p, gfx_yu2
			push hl
			ld hl, (gfx_dy)
			add hl, de
			ex de, hl
			pop hl
			rrc c
			jr nc, gfx_yu2
			inc hl
gfx_yu2:
			ld a, c
			and iyl
			xor (hl)
			ld (hl), a
			djnz gfx_yu
			ld a, (gfx_out)
			dec a
			ld (gfx_out), a
			jr nz, gfx_yu
			ret
; DE = a count: B = its low byte (0 = 256), gfx_out = rounds of B; Z when 0
gfx_cnt:
			ld a, d
			or e
			ret z
			ld b, e
			ld a, e
			or a
			jr z, gfx_cn1
			inc d
gfx_cn1:
			ld a, d
			ld (gfx_out), a
			or 1
			ret
; <gfxhi
	IF NTC_CPMGFX
; gfx_cpmdraw - CP/M on an Amstrad CPC, mode 2 (the console's). CP/M 2.2: the
; screen is #C000 of the program's own 64K: drawn there. CP/M Plus: the program
; runs in RAM configuration C2 (blocks 4-7) and the screen is block 1, at #4000
; only in C1 (blocks 0, 1, 2, 7), where nothing of the program but #C000-#FFFF
; (block 7, common) is left: the first line copies the loop to GFH_AT, and
; each line copies its numbers there and draws with the copy (gfh_go)
gfx_cpmdraw:
			ld a, (gfx_cpm)
			or a
			call z, gfx_cpmver
			cp #30
			jp c, gfx_l_draw		; 2.2
			ld a, h					; Plus: the address worked out for #C000 (gfx_base): #4000 in C1
			sub #80
			ld h, a
			push bc
			push hl
			ld hl, gfx_dx
			ld de, gfh_dx
			ld bc, 6
			ldir
			pop hl
			pop bc
			jp gfh_go
; gfx_cpmver - A = gfx_cpm = the CP/M version (BDOS 12: #22, #31); Plus: the
; copy put in common memory, the heap kept below GFH_AT
gfx_cpmver:
			push bc
			push de
			push hl
			push ix
			push iy
			ld a, i					; P/V = interrupts on (BDOS may turn them on)
			push af
			ld c, 12
			call 5
			di
			pop af
			jp po, gfx_cv1
			ei
gfx_cv1:
			pop iy
			pop ix
			ld a, l
			cp #30
			jr c, gfx_cv2
			ld hl, gfh_src
			ld de, GFH_AT
			ld bc, gfh_end - gfh_start
			ldir
			ld hl, GFH_AT
			ld (ntc_cpmtop), hl
			ld a, #31
gfx_cv2:
			ld (gfx_cpm), a
			pop hl
			pop de
			pop bc
			ret
gfx_cpm:		db 0			; the CP/M version, 0 = not looked at yet
	ENDIF
; HL = a coordinate, DE = the limit: carry when HL is not 0 .. DE - 1
gfx_chk:
			bit 7, h
			scf
			ret nz
			or a
			sbc hl, de
			ccf
			ret
gfx_neg:
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
			ret
; gfx_pat - IYL = the pen's bits for this mode (both / all pixels of a byte)
gfx_pat:
			ld a, (gfx_pen)
			ld b, a
			ld a, (ntc_smode)
			or a
			jr z, gfx_pt0
			dec a
			jr z, gfx_pt1
			ld a, b					; mode 2: pen 1 = every bit
			and 1
			jr z, gfx_ptset
			ld a, #FF
			jr gfx_ptset
gfx_pt1:
			xor a					; mode 1: pen bit 0 in the high nibble, bit 1 low
			bit 0, b
			jr z, gfx_pt1b
			or #F0
gfx_pt1b:
			bit 1, b
			jr z, gfx_ptset
			or #0F
			jr gfx_ptset
gfx_pt0:
			xor a					; mode 0: bit 0 -> 7, 1 -> 3, 2 -> 5, 3 -> 1 (and one
			bit 0, b				; to the right for the second pixel)
			jr z, gfx_p01
			or #C0
gfx_p01:
			bit 1, b
			jr z, gfx_p02
			or #0C
gfx_p02:
			bit 2, b
			jr z, gfx_p03
			or #30
gfx_p03:
			bit 3, b
			jr z, gfx_ptset
			or #03
gfx_ptset:
			ld iyl, a
			ret

; gfx_flip - double buffering: wait for the frame flyback, show the screen
; just drawn, draw on the other one from now on
gfx_flip:
			ld a, (gfx_dbl)
			or a
			ret z
			ld b, #F5				; wait for the vertical sync to start
gfx_fw1:
			in a, (c)
			rra
			jr c, gfx_fw1
gfx_fw2:
			in a, (c)
			rra
			jr nc, gfx_fw2
			ld a, (gfx_base)		; show it: CRTC R12 #30 (#C000) / #10 (#4000)
			cp #C0
			ld a, #30
			ld e, #40
			jr z, gfx_fl1
			ld a, #10
			ld e, #C0
gfx_fl1:
			ld (gfx_shown), a
			ld bc, #BC0C
			out (c), c
			inc b
			out (c), a
			ld a, e
			ld (gfx_base), a
			ret

; gfx_double - A = 1: double buffering on (the screen at #C000 copied to
; #4000, which is drawn on first), 0: off (#C000 shown and drawn on)
gfx_double:
	IF NTC_CPMGFX
			ret						; CP/M: one screen
	ENDIF
			or a
			jr z, gfx_dboff
			ld (gfx_dbl), a
			ld a, #C0				; show #C000 now
			call gfx_dshow
			ld bc, #7FC0
			out (c), c
			ld hl, #C000
			ld de, #4000
			ld bc, #4000
			ldir
			ld bc, (ntc_rampt)
			out (c), c
			ld a, #40
			ld (gfx_base), a
			ret
gfx_dboff:
			ld (gfx_dbl), a
			ld a, #C0
			ld (gfx_base), a
gfx_dshow:
			ld a, #30
			ld (gfx_shown), a
			ld bc, #BC0C
			out (c), c
			inc b
			out (c), a
			ret

; gfx_copyrows - A = text rows from the top: copied from #C000 to #4000 (so
; text printed while double buffering shows on both screens)
gfx_copyrows:
	IF NTC_CPMGFX
			ret						; CP/M: one screen
	ENDIF
			or a
			ret z
			ld e, a
			ld bc, #7FC0
			out (c), c
			ld d, 8					; 8 lines a row
			ld hl, #C000
gfx_cr1:
			push hl
			push de
			ld b, 0
			ld c, e					; rows * 80 bytes
			ld a, 80
			ld h, b
			ld l, b
gfx_cr2:
			add hl, bc
			dec a
			jr nz, gfx_cr2
			ld b, h
			ld c, l
			pop de
			pop hl
			push hl
			push de
			push hl
			ld a, h
			sub #80
			ld d, a
			ld e, l
			pop hl
			ldir
			pop de
			pop hl
			ld a, h
			add a, 8
			ld h, a
			dec d
			jr nz, gfx_cr1
			ld bc, (ntc_rampt)
			out (c), c
			ret

ntc_rg143_e:
			IF ($ < 37888) && (ntc_rg144_e - ntc_rg144 + $ > 16384)	; fwdref-ok
			ds 37888 - $		; Option Reserve #4000-#93FF: round it
			ENDIF
ntc_rg144:
;## kw_bssinit ntc_data ntc_plat_memtop ntc_plat_screen kw_stop @shared
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  it (from ntc_end, not in its file). Check they fit under the platform's top (and 256 bytes
;  under the real stack when that is above them), then clear them. Too big: a message, the
;  program stops.
kw_bssinit:
			pop hl
			ld (ntc_bsa), hl
			pop bc
			ld (ntc_bsz), bc
			ld (ntc_bsp), sp
			ld sp, (ntc_csp)
			add hl, bc				; HL = their end
			ex de, hl
			call ntc_plat_memtop	; HL = the platform's top
			or a
			sbc hl, de
			jr c, ntc_bs_big
			ld hl, (ntc_csp)		; the real stack, when above them
			ld bc, (ntc_bsa)
			or a
			sbc hl, bc
			jr c, ntc_bs_ok
			ld hl, (ntc_csp)
			ld bc, -256
			add hl, bc
			or a
			sbc hl, de
			jr c, ntc_bs_big
ntc_bs_ok:
			ld bc, (ntc_bsz)
			ld a, b
			or c
			jr z, ntc_bs_done
			ld hl, (ntc_bsa)
			ld (hl), 0
			dec bc
			ld a, b
			or c
			jr z, ntc_bs_done
			ld d, h
			ld e, l
			inc de
			ldir
ntc_bs_done:
			ld sp, (ntc_bsp)
			ret
ntc_bs_big:
			ld hl, ntc_bstxt
ntc_bs_pl:
			ld a, (hl)
			or a
			jr z, ntc_bs_stop
			inc hl
			ld (ntc_bsa), hl
			ld ix, ntc_bs_pn
			jp ntc_plat_putc
ntc_bs_pn:
			ld hl, (ntc_bsa)
			jr ntc_bs_pl
ntc_bs_stop:
			ld ix, kw_stop
			jp ntc_plat_newline
ntc_bsa:		dw 0
ntc_bsz:		dw 0
ntc_bsp:		dw 0
ntc_bstxt:		db "Not enough memory for the arrays", 0

ntc_rg144_e:
			IF ($ < 37888) && (ntc_rg145_e - ntc_rg145 + $ > 16384)	; fwdref-ok
			ds 37888 - $		; Option Reserve #4000-#93FF: round it
			ENDIF
ntc_rg145:
;## ntc_plat_data
ntc_curx:		db 0			; cursor column (0 based) - kept here for Tab
ntc_cury:		db 0			; cursor row (0 based)
ntc_scols:		db 40			; columns in this mode
ntc_smode:		db 1			; screen mode (for the Graphics class)
ntc_fwa:		db 0			; ntc_fwcall: A on return
ntc_fwwrap:		db 0			; 1 = the last character made the firmware wrap
ntc_irqset:		db 0			; 1 = the firmware's fast ticker calls ntc_fwevt
ntc_irqv:		dw 0			; interrupt classes' counting (ntc_isl_tick), 0 = none
ntc_irqix:		dw 0
NTC_FWBLK	equ #A5F0		; the fast ticker's event block (central 32K, below the firmware)
ntc_fwtop:		dw #A600		; the top of free RAM (#A5F0 with the fast ticker's block)
ntc_fwblk:		dw NTC_FWBLK		; the fast ticker's event block: lower (and the top with it) when the ROMs
								; started take more RAM than AMSDOS's #A700-#ABFF (Option RomEnable)

ntc_rg145_e:
			IF ($ < 37888) && (ntc_rg146_e - ntc_rg146 + $ > 16384)	; fwdref-ok
			ds 37888 - $		; Option Reserve #4000-#93FF: round it
			ENDIF
ntc_rg146:
;## ntc_plat_fw ntc_plat_data ntc_data @shared
; ------------------------------------------------------------
; ntc_fwcall - IY = firmware address; A, BC, DE, HL go in and come
; back as the firmware leaves them (A also in ntc_fwa, carry kept).
; IX is kept. Interrupts are on during the call.
; ------------------------------------------------------------
ntc_fwcall:
			ld (ntc_hostix), ix
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
			call ntc_fwjp
			di
			ld sp, (ntc_ip)
			ld (ntc_fwa), a
			ld ix, (ntc_hostix)
			jp (ix)
ntc_fwjp:
			jp (iy)

ntc_rg146_e:
			IF ($ < 37888) && (ntc_rg147_e - ntc_rg147 + $ > 16384)	; fwdref-ok
			ds 37888 - $		; Option Reserve #4000-#93FF: round it
			ENDIF
ntc_rg147:
;## ntc_plat_screen ntc_plat_fw ntc_plat_data ntc_data
; ntc_plat_putc - A = character: TXT OUTPUT. The firmware wraps by itself after
; the last column, so only the column is counted here; a new line straight after
; that wrap is left out (it would leave an empty line)
ntc_plat_putc:
			ld iy, #BB5A			; TXT OUTPUT
			ld (ntc_pclink), ix
			ld ix, ntc_pc_back
			jp ntc_fwcall
ntc_pc_back:
			ld ix, (ntc_pclink)
			xor a
			ld (ntc_fwwrap), a
			ld a, (ntc_scols)
			ld b, a
			ld a, (ntc_curx)
			inc a
			ld (ntc_curx), a
			cp b
			jr nz, ntc_pc_done
			xor a				; the firmware wrapped to the next line
			ld (ntc_curx), a
			inc a
			ld (ntc_fwwrap), a
ntc_pc_done:
			jp (ix)

; ntc_plat_newline - CR LF (the firmware scrolls); nothing straight after a wrap
ntc_plat_newline:
			ld a, (ntc_fwwrap)
			or a
			jr z, ntc_nl_go
			xor a
			ld (ntc_fwwrap), a
			jp (ix)
ntc_nl_go:
			ld (ntc_pclink), ix
			ld a, 13
			ld iy, #BB5A
			ld ix, ntc_nl_lf
			jp ntc_fwcall
ntc_nl_lf:
			ld a, 10
			ld iy, #BB5A
			ld ix, ntc_nl_done
			jp ntc_fwcall
ntc_nl_done:
			xor a
			ld (ntc_curx), a
			ld a, (ntc_cury)
			inc a
			cp 25
			jr c, ntc_nl_row
			ld a, 24
ntc_nl_row:
			ld (ntc_cury), a
			ld ix, (ntc_pclink)
			jp (ix)

ntc_pclink:		dw 0

ntc_rg147_e:
			IF ($ < 37888) && (ntc_rg148_e - ntc_rg148 + $ > 16384)	; fwdref-ok
			ds 37888 - $		; Option Reserve #4000-#93FF: round it
			ENDIF
ntc_rg148:
;## ntc_plat_cls @unit ntc_plat_screen ntc_plat_fw ntc_plat_data ntc_data
; ntc_plat_cls - TXT CLEAR WINDOW, cursor home
ntc_plat_cls:
			xor a
			ld (ntc_fwwrap), a
			ld (ntc_curx), a
			ld (ntc_cury), a
			ld iy, #BB6C			; TXT CLEAR WINDOW
			jp ntc_fwcall

ntc_rg148_e:
			IF ($ < 37888) && (ntc_rg149_e - ntc_rg149 + $ > 16384)	; fwdref-ok
			ds 37888 - $		; Option Reserve #4000-#93FF: round it
			ENDIF
ntc_rg149:
;## ntc_plat_mode @unit ntc_plat_screen ntc_plat_fw ntc_plat_data ntc_data
; ntc_plat_mode - A = mode 0-2 (3 = 2): SCR SET MODE (clears)
ntc_plat_mode:
			cp 3
			jr c, ntc_md_ok
			ld a, 2
ntc_md_ok:
			ld b, 20
			or a
			jr z, ntc_md_set
			ld b, 40
			cp 1
			jr z, ntc_md_set
			ld b, 80
ntc_md_set:
			ld (ntc_smode), a
			ld c, a
			ld a, b
			ld (ntc_scols), a
			xor a
			ld (ntc_fwwrap), a
			ld (ntc_curx), a
			ld (ntc_cury), a
			ld a, c
			ld iy, #BC0E			; SCR SET MODE
			jp ntc_fwcall

ntc_rg149_e:
			IF ($ < 37888) && (ntc_rg150_e - ntc_rg150 + $ > 16384)	; fwdref-ok
			ds 37888 - $		; Option Reserve #4000-#93FF: round it
			ENDIF
ntc_rg150:
;## ntc_plat_locate @unit ntc_plat_screen ntc_plat_fw ntc_plat_data ntc_data
; ntc_plat_locate - H = column, L = row, 1 based: TXT SET CURSOR
ntc_plat_locate:
			ld a, h
			or a
			jr nz, ntc_lc_x
			inc h
ntc_lc_x:
			ld a, l
			or a
			jr nz, ntc_lc_y
			inc l
ntc_lc_y:
			xor a
			ld (ntc_fwwrap), a
			ld a, h
			dec a
			ld (ntc_curx), a
			ld a, l
			dec a
			ld (ntc_cury), a
			ld iy, #BB75			; TXT SET CURSOR
			jp ntc_fwcall

ntc_rg150_e:
			IF ($ < 37888) && (ntc_rg151_e - ntc_rg151 + $ > 16384)	; fwdref-ok
			ds 37888 - $		; Option Reserve #4000-#93FF: round it
			ENDIF
ntc_rg151:
;## ntc_plat_key ntc_plat_fw ntc_data
; ntc_plat_scankey - A = key from the firmware's buffer, or 0
ntc_plat_scankey:
			ld (ntc_kslink), ix
			ld iy, #BB09			; KM READ CHAR
			ld ix, ntc_ks_back
			jp ntc_fwcall
ntc_ks_back:
			ld ix, (ntc_kslink)
			jr c, ntc_ks_got
			xor a
			jp (ix)
ntc_ks_got:
			ld a, (ntc_fwa)
			jp (ix)

; ntc_plat_getkey - wait for a key: KM WAIT CHAR
ntc_plat_getkey:
			ld iy, #BB06			; KM WAIT CHAR
			jp ntc_fwcall
ntc_kslink:		dw 0

ntc_rg151_e:
			IF ($ < 37888) && (ntc_rg152_e - ntc_rg152 + $ > 16384)	; fwdref-ok
			ds 37888 - $		; Option Reserve #4000-#93FF: round it
			ENDIF
ntc_rg152:
;## ntc_plat_ticks ntc_plat_fw
; ntc_plat_ticks - HL = the firmware's 1/300 s clock (KL TIME PLEASE, low word)
ntc_plat_ticks:
			ld iy, #BD0D
			jp ntc_fwcall

ntc_rg152_e:
			IF ($ < 37888) && (ntc_rg153_e - ntc_rg153 + $ > 16384)	; fwdref-ok
			ds 37888 - $		; Option Reserve #4000-#93FF: round it
			ENDIF
ntc_rg153:
;## ntc_plat_exit ntc_plat_data ntc_plat_fw
ntc_plat_exit:
			ld bc, #7FC0		; RAM setting back to plain (a Memory page may be in #4000)
			out (c), c
			ld a, (ntc_irqset)	; the fast ticker out of the firmware's list
			or a
			jr z, ntc_ex_done
			xor a
			ld (ntc_irqset), a
			ld (ntc_irqix), ix
			ld hl, (ntc_fwblk)
			ld iy, #BCE6		; KL DEL FAST TICKER
			ld ix, ntc_ex_back
			jp ntc_fwcall
ntc_ex_back:
			ld ix, (ntc_irqix)
ntc_ex_done:
			jp (ix)

ntc_rg153_e:
			IF ($ < 37888) && (ntc_rg154_e - ntc_rg154 + $ > 16384)	; fwdref-ok
			ds 37888 - $		; Option Reserve #4000-#93FF: round it
			ENDIF
ntc_rg154:
;## ntc_plat_memtop ntc_plat_data
; ntc_plat_memtop - HL = the first byte the Memory class's Small heap must not
; use: #A600 (the firmware's and AMSDOS's RAM is above), #A5F0 when the fast
; ticker's event block is there (Interrupt, interrupt classes). Called on the
; real stack (call / ret).
ntc_plat_memtop:
			ld hl, (ntc_fwtop)
			ret


ntc_rg154_e:
ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
			IF (ntc_bssfrom < 37888) && (ntc_bssfrom + ntc_bss_size > 16384)	; fwdref-ok
ntc_bss		equ 37888		; after Option Reserve #4000-#93FF
			ELSE
ntc_bss		equ ntc_bssfrom
			ENDIF
arr_city_bas		equ ntc_bss + 0		; 18 bytes
ntc_bss_size	equ 18
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
			IF ntc_free <= 37888	; fwdref-ok
ntc_memtab	equ 37888		; the Memory class's tables: above the window (Option Reserve)
			ELSE
ntc_memtab	equ ntc_free
			ENDIF
; Option Reserve: the program and its arrays (ntc_start .. ntc_free) must stay out of these
			ASSERT (ntc_free <= 16384) || (ntc_bss >= 32768), "the program (or its arrays) reaches into Option Reserve #4000-#7FFF (Main.bas line 9)"
			ASSERT (ntc_free <= 32768) || (ntc_bss >= 37888), "the program (or its arrays) reaches into Option Reserve #8000-#93FF (Main.bas line 10)"
